--- 并行任务将运行每个子任务，直到一个子任务返回失败。
--- 不同的是，并行任务将同时运行其所有的子任务，而不是一次运行每个任务。
--- 像序列类一样，一旦它的所有子任务都返回成功，并行任务将返回成功。
--- 如果一个任务返回失败，并行任务将结束所有的子任务并返回失败。

------------ import ------------
local Composite = import("Frame.AI.BT.Composites.Composite")
------------ import ------------

------------ define ------------

------------ define ------------

---@class Parallel
local Parallel = Class("Parallel", Composite)

function Parallel:__init()
    Composite.__init(self)
end

function Parallel:__delete()
    
end

function Parallel:Update(context)
    local didAllSucceed = true
    ---@type BT.Composite[]
    local children = self._children
    for i, child in ipairs(children) do
        local status = child:Tick(context)

        ---如果任何一个子节点失败了，整个分支都会失败
        if status == Composite.TaskStatus.Failure then
            return Composite.TaskStatus.Failure
            
        --- 如果所有的子节点没有成功，我们还没有完成
        elseif status ~= Composite.TaskStatus.Success then
            didAllSucceed = false
        end
        
    end

    if didAllSucceed then
        return Composite.TaskStatus.Success
    end
    return Composite.TaskStatus.Running
end


return Parallel
 